window.MVQ = [{"id": "1ac-milieu-naturel", "level": "1", "theme": "Écologie", "title": "Le milieu naturel et ses facteurs", "prepare": [{"q": "Une pierre est un être vivant.", "a": false, "e": "Une pierre ne se nourrit pas, ne respire pas, ne se reproduit pas."}, {"q": "Les plantes ont besoin de lumière.", "a": true, "e": "Les plantes vertes utilisent la lumière pour fabriquer leur matière."}, {"q": "Il fait souvent plus frais à l'ombre qu'au soleil.", "a": true, "e": "L'ombre reçoit moins de lumière et de chaleur."}], "seul": [{"lvl": 1, "q": "Lequel est un facteur physique du milieu ?", "a": 0, "o": ["la température", "le champignon", "le lézard"], "e": "Les deux autres sont des êtres vivants."}, {"lvl": 2, "q": "Un écosystème est formé :", "a": 1, "o": ["des seuls animaux", "du biotope et de la biocénose", "des seules plantes"], "e": "Avec les relations entre eux."}, {"lvl": 3, "q": "On mesure 200 lux à l'ombre et 40 000 lux au soleil. Où trouve-t-on surtout les mousses ?", "a": 0, "o": ["à 200 lux", "à 40 000 lux"], "e": "Les mousses préfèrent les endroits peu éclairés et humides."}, {"lvl": 4, "q": "On coupe les cèdres d'une partie de la forêt. Que devient le sol de cette partie ?", "a": 0, "o": ["plus éclairé et plus sec", "plus sombre et plus humide", "il ne change pas"], "e": "Les arbres faisaient de l'ombre : les mousses risquent de reculer."}]}, {"id": "1ac-respiration", "level": "1", "theme": "Les êtres vivants", "title": "La respiration chez les êtres vivants", "prepare": [{"q": "Les animaux ont besoin de dioxygène pour vivre.", "a": true, "e": "Ils le prennent dans l'air ou dans l'eau."}, {"q": "L'eau d'une rivière ne contient pas de dioxygène.", "a": false, "e": "Le dioxygène y est dissous : les poissons l'utilisent."}, {"q": "Les plantes respirent aussi.", "a": true, "e": "Comme tous les êtres vivants, jour et nuit."}], "seul": [{"lvl": 1, "q": "En respirant, un être vivant rejette :", "a": 1, "o": ["du dioxygène", "du dioxyde de carbone", "de l'azote"]}, {"lvl": 2, "q": "L'organe respiratoire du poisson est :", "a": 1, "o": ["les poumons", "les branchies", "les trachées"]}, {"lvl": 3, "q": "Un bocal fermé avec une plante, à l'obscurité : l'eau de chaux se trouble. Pourquoi ?", "a": 0, "o": ["La plante respire et rejette du dioxyde de carbone.", "La plante ne respire pas.", "L'obscurité trouble l'eau de chaux."], "e": "Les plantes respirent aussi."}, {"lvl": 4, "q": "Le têtard vit dans l'eau, la grenouille adulte surtout dans l'air. Leurs organes respiratoires :", "a": 1, "o": ["sont les mêmes", "changent : branchies puis poumons", "n'existent pas"], "e": "L'organe respiratoire est adapté au milieu de vie."}]}, {"id": "1ac-regimes-alimentaires", "level": "1", "theme": "Les êtres vivants", "title": "Les régimes alimentaires des animaux", "prepare": [{"q": "Tous les animaux mangent la même nourriture.", "a": false, "e": "Chaque espèce a son régime alimentaire."}, {"q": "Les plantes vertes fabriquent leur propre matière.", "a": true, "e": "Elles n'ont pas besoin de manger d'autres êtres vivants."}, {"q": "Les dents servent à couper et broyer les aliments.", "a": true, "e": "Leur forme dépend de ce que l'animal mange."}], "seul": [{"lvl": 1, "q": "Un animal qui mange seulement des végétaux est :", "a": 0, "o": ["herbivore", "carnivore", "omnivore"]}, {"lvl": 2, "q": "L'Homme est :", "a": 2, "o": ["herbivore", "carnivore", "omnivore"]}, {"lvl": 3, "q": "Des molaires larges et plates indiquent un régime :", "a": 0, "o": ["herbivore", "carnivore"]}, {"lvl": 4, "q": "Le têtard mange des algues, la grenouille adulte des insectes. On dit que le régime :", "a": 0, "o": ["change avec l'âge", "ne change jamais"]}]}, {"id": "1ac-chaines-alimentaires", "level": "1", "theme": "Écologie", "title": "Chaînes et réseaux alimentaires", "prepare": [{"q": "Les plantes vertes fabriquent leur propre matière.", "a": true, "e": "Ce sont des producteurs."}, {"q": "Le lézard mange de l'herbe.", "a": false, "e": "Le lézard est carnivore : il mange des insectes."}, {"q": "Un animal peut être mangé par un autre animal.", "a": true, "e": "C'est une relation alimentaire."}], "seul": [{"lvl": 1, "q": "Dans une chaîne alimentaire, le premier maillon est toujours :", "a": 0, "o": ["un producteur (plante verte)", "un carnivore"]}, {"lvl": 2, "q": "La flèche « herbe → criquet » signifie :", "a": 1, "o": ["l'herbe mange le criquet", "l'herbe est mangée par le criquet"]}, {"lvl": 3, "q": "Dans « herbe → criquet → lézard → faucon », combien de consommateurs ?", "a": 3}, {"lvl": 4, "q": "Si on utilise un insecticide qui tue les criquets, les lézards risquent de :", "a": 0, "o": ["diminuer", "augmenter"]}]}, {"id": "1ac-classification", "level": "1", "theme": "Les êtres vivants", "title": "Classer les êtres vivants", "prepare": [{"q": "Tous les animaux qui volent sont des oiseaux.", "a": false, "e": "Les insectes et les chauves-souris volent aussi."}, {"q": "La poule a des plumes.", "a": true, "e": "Les plumes caractérisent les oiseaux."}, {"q": "Le lézard a un squelette interne.", "a": true, "e": "C'est un vertébré."}], "seul": [{"lvl": 1, "q": "Un animal à plumes est un :", "a": 0, "o": ["oiseau", "mammifère"]}, {"lvl": 2, "q": "La grenouille, à peau nue et humide, est un :", "a": 0, "o": ["amphibien", "reptile", "poisson"]}, {"lvl": 3, "q": "Le dauphin a des poils à la naissance et allaite : c'est un", "a": 0, "o": ["mammifère", "poisson"]}, {"lvl": 4, "q": "Dans la clé, combien de groupes de vertébrés distingue-t-on ?", "a": 5}]}, {"id": "1ac-sedimentation", "level": "1", "theme": "Géologie", "title": "Le cycle sédimentaire et les fossiles", "prepare": [{"q": "La pluie et le vent usent lentement les roches.", "a": true, "e": "C'est l'érosion."}, {"q": "Les rivières transportent du sable et de la boue.", "a": true, "e": "Jusqu'aux lacs et aux mers."}, {"q": "Une couche déposée en dernier se trouve en bas.", "a": false, "e": "Elle se dépose au-dessus des autres."}], "seul": [{"lvl": 1, "q": "L'usure des roches par la pluie et le vent s'appelle :", "a": 0, "o": ["l'érosion", "la sédimentation"]}, {"lvl": 2, "q": "Le dépôt des grains au fond de l'eau s'appelle :", "a": 0, "o": ["la sédimentation", "le transport"]}, {"lvl": 3, "q": "Dans une série de couches non déformées, la couche du haut est :", "a": 0, "o": ["la plus récente", "la plus ancienne"]}, {"lvl": 4, "q": "Une couche de 3 m s'est déposée à 1 cm par siècle. Combien de siècles ?", "a": 300, "hint": "3 m = 300 cm."}]}, {"id": "1ac-ressources-eau", "level": "1", "theme": "Géologie", "title": "Les ressources en eau", "prepare": [{"q": "L'eau de mer est salée.", "a": true, "e": "On ne peut pas la boire sans la dessaler."}, {"q": "Toute l'eau de pluie reste à la surface du sol.", "a": false, "e": "Une partie s'infiltre dans le sol."}, {"q": "Le Maroc connaît des périodes de sécheresse.", "a": true, "e": "L'eau douce y est précieuse."}], "seul": [{"lvl": 1, "q": "La transformation de l'eau liquide en vapeur s'appelle :", "a": 0, "o": ["l'évaporation", "la condensation"]}, {"lvl": 2, "q": "L'eau qui pénètre dans le sol :", "a": 0, "o": ["s'infiltre", "ruisselle"]}, {"lvl": 3, "q": "Une nappe phréatique est une réserve d'eau :", "a": 0, "o": ["souterraine", "de surface"]}, {"lvl": 4, "q": "Un robinet qui fuit perd 5 L par heure. Combien de litres par jour ?", "a": 120, "unit": "L"}]}, {"id": "2ac-tectonique", "level": "2", "theme": "Géologie", "title": "Les plaques bougent", "prepare": [{"q": "Un fossile est un reste ou une trace d'un être vivant ancien.", "a": true, "e": "Conservé dans les roches."}, {"q": "Le sol sous nos pieds ne bouge jamais.", "a": false, "e": "Il bouge très lentement, de quelques millimètres à quelques centimètres par an."}, {"q": "Les séismes sont des secousses du sol.", "a": true, "e": "En arabe : الزلازل."}], "seul": [{"lvl": 1, "q": "La surface de la Terre est formée :", "a": 1, "o": ["d'un seul bloc immobile", "de plaques qui bougent", "de plaques qui bougent de plusieurs mètres par jour"], "e": "Elles bougent de quelques centimètres par an."}, {"lvl": 2, "q": "Deux plaques qui se rapprochent provoquent :", "a": 1, "o": ["l'ouverture d'un océan", "la formation de montagnes et des séismes", "aucun effet"], "e": "C'est la convergence."}, {"lvl": 3, "q": "L'Atlantique s'élargit d'environ 2 cm par an. De combien de kilomètres en 1 million d'années ?", "a": 20, "unit": "km", "hint": "2 cm × 1 000 000 = 2 000 000 cm = 20 km."}, {"lvl": 4, "q": "Pourquoi trouve-t-on des fossiles marins dans l'Atlas ?", "a": 1, "o": ["La mer montait jusqu'aux sommets.", "Des roches formées au fond de la mer ont été plissées et soulevées.", "Des oiseaux les ont transportés."], "e": "Les sédiments marins ont été soulevés par le rapprochement des plaques."}]}, {"id": "2ac-seismes", "level": "2", "theme": "Géologie", "title": "Les séismes", "prepare": [{"q": "Les roches sous nos pieds peuvent se casser.", "a": true, "e": "Quand les forces sont trop grandes, elles cassent brusquement."}, {"q": "Un séisme ne se produit qu'au bord de la mer.", "a": false, "e": "Il peut se produire en montagne, comme dans le Haut Atlas."}, {"q": "Une onde se propage, comme les ronds dans l'eau.", "a": true, "e": "Elle part d'un point et s'éloigne dans toutes les directions."}], "seul": [{"lvl": 1, "q": "Le point en profondeur où les roches cassent s'appelle :", "a": 0, "o": ["le foyer", "l'épicentre", "le sismographe"], "e": "L'épicentre est en surface, au-dessus du foyer."}, {"lvl": 2, "q": "Quand on s'éloigne de l'épicentre, l'intensité :", "a": 0, "o": ["diminue", "augmente", "reste la même"], "e": "Les effets sont plus faibles loin de l'épicentre."}, {"lvl": 3, "q": "Une onde parcourt 5 km par seconde. Elle atteint une station située à 150 km. En combien de secondes ?", "a": 30, "unit": "s", "hint": "150 ÷ 5."}, {"lvl": 4, "q": "Pourquoi la plupart des séismes se produisent-ils aux limites des plaques ?", "a": 1, "o": ["Il y fait plus chaud.", "Les plaques s'y frottent et les roches finissent par casser.", "La mer y est plus profonde."], "e": "Les forces dues au mouvement des plaques s'y accumulent."}]}, {"id": "2ac-volcans", "level": "2", "theme": "Géologie", "title": "Les volcans", "prepare": [{"q": "Le miel froid coule plus lentement que l'eau.", "a": true, "e": "On dit qu'il est plus visqueux."}, {"q": "Une bouteille de boisson gazeuse secouée peut jaillir à l'ouverture.", "a": true, "e": "Les gaz s'échappent brutalement : c'est la même idée dans un volcan explosif."}, {"q": "Tous les volcans du Maroc sont en activité.", "a": false, "e": "Les volcans du Moyen Atlas et du Siroua sont éteints."}], "seul": [{"lvl": 1, "q": "Le conduit par lequel monte le magma s'appelle :", "a": 0, "o": ["la cheminée", "la coulée", "la cendre"], "e": "Il relie la chambre magmatique au cratère."}, {"lvl": 2, "q": "Une lave fluide donne une éruption :", "a": 0, "o": ["effusive", "explosive"], "e": "Les gaz s'échappent facilement, la lave coule."}, {"lvl": 3, "q": "Une lave sort à 1 150 °C et se solidifie vers 700 °C. De combien de degrés a-t-elle refroidi ?", "a": 450, "unit": "°C", "hint": "1 150 − 700."}, {"lvl": 4, "q": "Pourquoi une lave visqueuse rend-elle l'éruption dangereuse ?", "a": 1, "o": ["Elle coule plus vite que l'eau.", "Ses gaz restent piégés puis s'échappent d'un coup.", "Elle ne contient aucun gaz."], "e": "La pression des gaz monte jusqu'à l'explosion."}]}, {"id": "2ac-roches-magmatiques", "level": "2", "theme": "Géologie", "title": "Les roches magmatiques", "prepare": [{"q": "Le magma est une roche fondue.", "a": true, "e": "Il est très chaud, plus de 700 °C."}, {"q": "Un cristal est un solide aux formes régulières, comme le sel ou le sucre.", "a": true, "e": "Les roches magmatiques sont faites de cristaux appelés minéraux."}, {"q": "Une roche magmatique contient souvent des fossiles.", "a": false, "e": "Elle vient d'un magma très chaud : les fossiles se trouvent dans les roches sédimentaires."}], "seul": [{"lvl": 1, "q": "Le granite a une structure :", "a": 0, "o": ["grenue", "microlitique"], "e": "Tous ses cristaux sont visibles à l'œil nu."}, {"lvl": 2, "q": "Le basalte s'est formé :", "a": 0, "o": ["par refroidissement rapide de la lave en surface", "par refroidissement lent du magma en profondeur"], "e": "Sa structure est microlitique."}, {"lvl": 3, "q": "Un granite contient 35 % de quartz et 55 % de feldspath. Le reste est du mica. Quel pourcentage de mica ?", "a": 10, "unit": "%", "hint": "100 − 35 − 55."}, {"lvl": 4, "q": "Le gabbro a la même composition que le basalte, mais avec de gros cristaux visibles. Il s'est donc formé :", "a": 0, "o": ["en profondeur, par refroidissement lent", "en surface, par refroidissement rapide"], "e": "C'est la vitesse de refroidissement qui fixe la taille des cristaux."}]}, {"id": "2ac-deformations", "level": "2", "theme": "Géologie", "title": "Les plis et les failles", "prepare": [{"q": "Les couches sédimentaires se déposent à l'horizontale.", "a": true, "e": "C'est le principe d'horizontalité."}, {"q": "Une roche dure ne peut jamais se plier.", "a": false, "e": "Poussée lentement pendant très longtemps, en profondeur, elle peut se plier."}, {"q": "Les plaques exercent des forces sur les roches.", "a": true, "e": "Elles se rapprochent ou s'écartent."}], "seul": [{"lvl": 1, "q": "Une cassure des roches avec déplacement des deux blocs s'appelle :", "a": 0, "o": ["une faille", "un pli", "un fossile"], "e": "Le pli est une déformation souple, sans cassure."}, {"lvl": 2, "q": "Un pli en creux s'appelle :", "a": 0, "o": ["un synclinal", "un anticlinal"], "e": "L'anticlinal est bombé vers le haut."}, {"lvl": 3, "q": "Une faille a un rejet total de 2 m, produit par 4 séismes de même taille. Quel déplacement par séisme, en centimètres ?", "a": 50, "unit": "cm", "hint": "200 cm ÷ 4."}, {"lvl": 4, "q": "Une région montre des plis et des failles inverses. Les roches ont subi :", "a": 0, "o": ["une compression", "une distension"], "e": "Les plaques se sont rapprochées."}]}, {"id": "2ac-chaines-montagnes", "level": "2", "theme": "Géologie", "title": "La formation des chaînes de montagnes", "prepare": [{"q": "Deux plaques peuvent se rapprocher.", "a": true, "e": "On parle de convergence."}, {"q": "Une plaque océanique est plus légère qu'un continent.", "a": false, "e": "Elle est plus dense, donc plus lourde à volume égal."}, {"q": "Les plis et les failles inverses sont dus à une compression.", "a": true, "e": "On les trouve dans les chaînes de montagnes."}], "seul": [{"lvl": 1, "q": "Le plongement d'une plaque océanique sous une autre plaque s'appelle :", "a": 0, "o": ["la subduction", "la collision", "l'érosion"], "e": "Elle forme une fosse océanique."}, {"lvl": 2, "q": "Une fosse océanique et de nombreux volcans caractérisent :", "a": 0, "o": ["une chaîne de subduction", "une chaîne de collision"], "e": "Exemple : les Andes."}, {"lvl": 3, "q": "Une plaque avance de 4 cm par an pendant 2 millions d'années. De combien de kilomètres ?", "a": 80, "unit": "km", "hint": "4 cm × 2 000 000 = 8 000 000 cm = 80 km."}, {"lvl": 4, "q": "Pourquoi trouve-t-on des fossiles marins au sommet de l'Himalaya ?", "a": 1, "o": ["La mer recouvrait l'Himalaya il y a cent ans.", "Un océan s'est fermé et ses sédiments ont été plissés et soulevés.", "Des oiseaux les ont apportés."], "e": "C'est la trace de l'océan qui séparait l'Inde de l'Asie."}]}, {"id": "2ac-reproduction-animaux", "level": "2", "theme": "Reproduction", "title": "La reproduction chez les animaux", "prepare": [{"q": "Chez la plupart des animaux, il existe un mâle et une femelle.", "a": true, "e": "La reproduction sexuée fait intervenir les deux."}, {"q": "Tous les animaux pondent des œufs.", "a": false, "e": "Les mammifères, par exemple, donnent naissance à des petits."}, {"q": "Un poussin sort d'un œuf.", "a": true, "e": "La poule est ovipare."}], "seul": [{"lvl": 1, "q": "Les gamètes mâles s'appellent :", "a": 1, "o": ["les ovules", "les spermatozoïdes", "les têtards"]}, {"lvl": 2, "q": "La fécondation, c'est :", "a": 1, "o": ["la ponte des œufs", "l'union d'un spermatozoïde et d'un ovule", "la sortie du têtard"]}, {"lvl": 3, "q": "Un animal qui pond des œufs est dit :", "a": 0, "o": ["ovipare", "vivipare"], "e": "Un animal dont les petits naissent vivants est vivipare."}, {"lvl": 4, "q": "Le têtard respire avec des branchies, la grenouille adulte surtout avec des poumons. Cela montre :", "a": 1, "o": ["un développement direct", "une métamorphose", "une fécondation interne"]}]}, {"id": "2ac-reproduction-plantes", "level": "2", "theme": "Reproduction", "title": "La reproduction des plantes à fleurs", "prepare": [{"q": "Une graine peut donner une nouvelle plante.", "a": true, "e": "Elle germe dans de bonnes conditions."}, {"q": "Toutes les fleurs deviennent des fruits.", "a": false, "e": "Seules les fleurs fécondées donnent des fruits."}, {"q": "Les abeilles visitent les fleurs.", "a": true, "e": "Elles y cherchent du nectar et transportent du pollen."}], "seul": [{"lvl": 1, "q": "L'organe mâle de la fleur est :", "a": 1, "o": ["le pistil", "l'étamine", "le pétale"]}, {"lvl": 2, "q": "Le transport du pollen jusqu'au pistil s'appelle :", "a": 1, "o": ["la fécondation", "la pollinisation", "la germination"]}, {"lvl": 3, "q": "Après la fécondation, l'ovaire devient :", "a": 1, "o": ["la graine", "le fruit", "la fleur"]}, {"lvl": 4, "q": "Pourquoi des pesticides qui tuent les abeilles peuvent réduire la récolte d'amandes ?", "a": 0, "o": ["Les abeilles assurent la pollinisation.", "Les abeilles mangent les amandes."]}]}, {"id": "2ac-reproduction-homme", "level": "2", "theme": "Reproduction", "title": "La reproduction chez l'Homme", "prepare": [{"q": "La puberté est la période où le corps devient capable de se reproduire.", "a": true, "e": "Elle commence en général entre 10 et 14 ans."}, {"q": "Chez l'Homme, la fécondation se fait hors du corps.", "a": false, "e": "Elle est interne : dans les voies génitales de la femme."}, {"q": "Les gamètes sont des cellules reproductrices.", "a": true, "e": "Spermatozoïdes chez l'homme, ovules chez la femme."}], "seul": [{"lvl": 1, "q": "Les spermatozoïdes sont produits par :", "a": 0, "o": ["les testicules", "les ovaires"]}, {"lvl": 2, "q": "L'union d'un spermatozoïde et d'un ovule s'appelle :", "a": 1, "o": ["l'ovulation", "la fécondation", "la puberté"]}, {"lvl": 3, "q": "Une grossesse dure environ combien de mois ?", "a": 9, "unit": "mois"}, {"lvl": 4, "q": "Le fœtus reçoit sa nourriture et son dioxygène :", "a": 0, "o": ["par le placenta, depuis le sang de la mère", "en respirant de l'air"]}]}, {"id": "2ac-heredite", "level": "2", "theme": "Reproduction", "title": "L'hérédité chez l'Homme", "prepare": [{"q": "Une cellule possède un noyau.", "a": true, "e": "Le noyau contient l'information héréditaire."}, {"q": "Le spermatozoïde vient de la mère.", "a": false, "e": "Il est produit par le père ; l'ovule vient de la mère."}, {"q": "La fécondation donne une cellule-œuf.", "a": true, "e": "Elle se divise pour former l'embryon."}], "seul": [{"lvl": 1, "q": "Les caractères héréditaires sont portés par :", "a": 0, "o": ["les chromosomes", "le sang"]}, {"lvl": 2, "q": "Combien de paires de chromosomes dans une cellule du corps ?", "a": 23}, {"lvl": 3, "q": "Une cellule-œuf XY donnera :", "a": 0, "o": ["un garçon", "une fille"]}, {"lvl": 4, "q": "Sur 2 spermatozoïdes, un porte X et l'autre Y. Chance d'avoir une fille, en % ?", "a": 50, "unit": "%"}]}, {"id": "3ac-digestion", "level": "3", "theme": "Nutrition", "title": "La digestion et l'absorption", "prepare": [{"q": "Le pain contient de l'amidon.", "a": true, "e": "L'amidon est le principal constituant de la farine."}, {"q": "Les aliments passent dans le sang dès la bouche, sans transformation.", "a": false, "e": "Ils doivent d'abord être transformés en très petites molécules."}, {"q": "Le sang circule dans tout le corps, jusqu'aux muscles.", "a": true, "e": "Il transporte ce dont les organes ont besoin."}], "seul": [{"lvl": 1, "q": "La digestion de l'amidon donne :", "a": 0, "o": ["du glucose", "des acides aminés", "des acides gras"], "e": "Amidon → glucose."}, {"lvl": 2, "q": "Le rôle des enzymes digestives est de :", "a": 1, "o": ["écraser les aliments", "couper les grosses molécules en petites", "transporter les nutriments dans le sang"], "e": "Elles réalisent la digestion chimique."}, {"lvl": 3, "q": "L'absorption intestinale, c'est :", "a": 0, "o": ["le passage des nutriments de l'intestin grêle vers le sang", "le mélange des aliments dans l'estomac", "la sortie des restes non digérés"], "e": "Elle se fait à travers la paroi de l'intestin grêle."}, {"lvl": 4, "q": "Après un repas riche en pain, où trouve-t-on le plus de glucose ?", "a": 0, "o": ["Dans le sang qui sort de l'intestin grêle", "Dans le sang qui arrive à l'intestin grêle", "Dans l'œsophage"], "e": "Le sang se charge en glucose en passant le long de l'intestin grêle."}]}, {"id": "3ac-respiration-homme", "level": "3", "theme": "Nutrition", "title": "La respiration chez l'Homme", "prepare": [{"q": "L'air entre par le nez ou la bouche.", "a": true, "e": "Puis il descend par la trachée."}, {"q": "L'air que l'on expire ne contient plus de dioxygène.", "a": false, "e": "Il en contient encore, environ 16 %, contre 21 % dans l'air inspiré."}, {"q": "Le sang circule dans tout le corps.", "a": true, "e": "Il transporte le dioxygène jusqu'aux organes."}], "seul": [{"lvl": 1, "q": "Pendant l'inspiration, le diaphragme :", "a": 0, "o": ["descend", "monte", "ne bouge pas"]}, {"lvl": 2, "q": "Les échanges gazeux respiratoires ont lieu :", "a": 1, "o": ["dans la trachée", "au niveau des alvéoles", "dans le nez"]}, {"lvl": 3, "q": "Une personne fait 15 respirations par minute. Combien en 10 minutes ?", "a": 150, "hint": "15 × 10."}, {"lvl": 4, "q": "Pourquoi la paroi des alvéoles est-elle très fine ?", "a": 0, "o": ["Pour faciliter le passage des gaz entre l'air et le sang.", "Pour retenir l'air plus longtemps.", "Pour filtrer la poussière."]}]}, {"id": "3ac-sang", "level": "3", "theme": "Nutrition", "title": "Le sang et la circulation", "prepare": [{"q": "Le sang est rouge à cause des globules rouges.", "a": true, "e": "Ils contiennent une substance rouge, l'hémoglobine."}, {"q": "Le sang reste immobile dans les vaisseaux.", "a": false, "e": "Il circule sans arrêt, poussé par le cœur."}, {"q": "Le cœur est un muscle.", "a": true, "e": "Il se contracte et pousse le sang."}], "seul": [{"lvl": 1, "q": "Quel constituant du sang défend l'organisme ?", "a": 0, "o": ["les globules blancs", "les plaquettes", "le plasma"]}, {"lvl": 2, "q": "Le glucose est transporté surtout par :", "a": 1, "o": ["les globules rouges", "le plasma"]}, {"lvl": 3, "q": "Après centrifugation, le plasma occupe environ 55 % d'un tube de 10 mL. Quel volume de plasma ?", "a": 5.5, "unit": "mL", "hint": "55 % de 10."}, {"lvl": 4, "q": "Les échanges entre le sang et les cellules se font au niveau :", "a": 0, "o": ["des capillaires", "du cœur", "des grosses artères"], "e": "Leur paroi très fine permet les échanges."}]}, {"id": "3ac-immunite", "level": "3", "theme": "Santé", "title": "L'immunité", "prepare": [{"q": "Les microbes sont des êtres vivants très petits, comme les bactéries.", "a": true, "e": "Certains provoquent des maladies."}, {"q": "La peau laisse entrer facilement tous les microbes.", "a": false, "e": "La peau intacte est une barrière efficace."}, {"q": "Les globules blancs font partie du sang.", "a": true, "e": "Ils participent à la défense de l'organisme."}], "seul": [{"lvl": 1, "q": "La première barrière contre les microbes est :", "a": 0, "o": ["la peau", "le cœur"]}, {"lvl": 2, "q": "La phagocytose est réalisée par :", "a": 0, "o": ["des globules blancs", "des globules rouges"]}, {"lvl": 3, "q": "Les anticorps sont produits par :", "a": 0, "o": ["les lymphocytes", "les plaquettes"]}, {"lvl": 4, "q": "Pourquoi fait-on souvent un rappel de vaccin ?", "a": 0, "o": ["pour entretenir la mémoire immunitaire", "pour soigner une fracture"]}]}, {"id": "3ac-nutrition", "level": "3", "theme": "Santé", "title": "L'éducation nutritionnelle", "prepare": [{"q": "Les aliments apportent de l'énergie au corps.", "a": true, "e": "Surtout les glucides et les lipides."}, {"q": "Un seul aliment suffit pour être en bonne santé.", "a": false, "e": "Aucun aliment ne contient tout : il faut varier."}, {"q": "Le lait est riche en calcium.", "a": true, "e": "Le calcium construit les os."}], "seul": [{"lvl": 1, "q": "Les lentilles apportent surtout :", "a": 0, "o": ["des protéines", "du calcium"]}, {"lvl": 2, "q": "Un excès de sucres peut provoquer :", "a": 0, "o": ["des caries et l'obésité", "une carence en sucre"]}, {"lvl": 3, "q": "Lequel est le plus équilibré ?", "a": 0, "o": ["pain, lait, orange, œuf", "soda, croissant", "chips, jus sucré"]}, {"lvl": 4, "q": "Énergie de 10 g de lipides, en kJ ?", "a": 380, "unit": "kJ"}]}, {"id": "3ac-systeme-nerveux", "level": "3", "theme": "Relation", "title": "Le système nerveux", "prepare": [{"q": "La peau contient des récepteurs sensibles à la chaleur.", "a": true, "e": "Ils captent la stimulation."}, {"q": "Les muscles se contractent sans recevoir de message.", "a": false, "e": "Ils obéissent à un message nerveux."}, {"q": "La moelle épinière est protégée par la colonne vertébrale.", "a": true, "e": "Elle se trouve dans le canal des vertèbres."}], "seul": [{"lvl": 1, "q": "Le nerf qui conduit le message vers le centre nerveux est :", "a": 0, "o": ["sensitif", "moteur"]}, {"lvl": 2, "q": "L'organe qui exécute la réponse est :", "a": 0, "o": ["le muscle", "le récepteur"]}, {"lvl": 3, "q": "Écrire une lettre est un mouvement commandé par :", "a": 0, "o": ["le cerveau", "la moelle épinière seule"]}, {"lvl": 4, "q": "Combien d'éléments dans le trajet du réflexe (récepteur, nerfs, centre, muscle) ?", "a": 5}]}, {"id": "3ac-systeme-musculaire", "level": "3", "theme": "Relation", "title": "Le système musculaire", "prepare": [{"q": "Les muscles sont attachés aux os par des tendons.", "a": true, "e": "Ce sont des cordons solides."}, {"q": "Un muscle peut pousser un os.", "a": false, "e": "Un muscle ne fait que tirer en se contractant."}, {"q": "Le coude est une articulation.", "a": true, "e": "Il relie le bras et l'avant-bras."}], "seul": [{"lvl": 1, "q": "Un muscle qui se contracte :", "a": 0, "o": ["raccourcit et grossit", "s'allonge"]}, {"lvl": 2, "q": "Le muscle qui tend l'avant-bras :", "a": 0, "o": ["le triceps", "le biceps"]}, {"lvl": 3, "q": "Deux muscles qui agissent en sens contraires sont :", "a": 0, "o": ["antagonistes", "identiques"]}, {"lvl": 4, "q": "Le corps humain compte environ 600 muscles. Si 40 % sont dans les membres, combien cela fait-il ?", "a": 240}]}, {"id": "3ac-micro-organismes", "level": "3", "theme": "Santé", "title": "Les micro-organismes", "prepare": [{"q": "Les micro-organismes ne sont visibles qu'au microscope.", "a": true, "e": "Ils mesurent quelques micromètres, ou moins."}, {"q": "Tous les microbes sont dangereux.", "a": false, "e": "Beaucoup sont utiles : yaourt, pain, fromage."}, {"q": "Se laver les mains limite la transmission des microbes.", "a": true, "e": "C'est un geste d'hygiène essentiel."}], "seul": [{"lvl": 1, "q": "Un micro-organisme qui provoque une maladie est :", "a": 0, "o": ["pathogène", "utile"]}, {"lvl": 2, "q": "La levure sert à fabriquer :", "a": 0, "o": ["le pain", "le sel"]}, {"lvl": 3, "q": "Les antibiotiques agissent sur :", "a": 0, "o": ["les bactéries", "les virus"]}, {"lvl": 4, "q": "Une bactérie se divise toutes les 20 min. Combien de bactéries après 1 h à partir d'une seule ?", "a": 8}]}, {"id": "3ac-reponses-immunitaires", "level": "3", "theme": "Santé", "title": "Les réponses immunitaires", "prepare": [{"q": "La phagocytose est une défense qui agit contre tous les microbes.", "a": true, "e": "Elle n'est pas spécifique."}, {"q": "Un anticorps agit contre n'importe quel microbe.", "a": false, "e": "Chaque anticorps est spécifique d'un antigène."}, {"q": "Les lymphocytes sont des globules blancs.", "a": true, "e": "Ils assurent la réponse spécifique."}], "seul": [{"lvl": 1, "q": "Les anticorps sont produits par :", "a": 0, "o": ["les lymphocytes B", "les globules rouges"]}, {"lvl": 2, "q": "La réponse au 2e contact avec le même antigène est :", "a": 0, "o": ["plus rapide et plus forte", "plus lente"]}, {"lvl": 3, "q": "La sérothérapie est :", "a": 0, "o": ["curative et de courte durée", "préventive et durable"]}, {"lvl": 4, "q": "Sur le graphe, le 1er contact a lieu au jour 2 et le pic au jour 16. Combien de jours d'attente ?", "a": 14}]}];
